def solve(n, a):
    left = []
    right = []
    while a:
        if not left or a[-1] > left[-1]:
            left.append(a.pop())
        else:
            right.append(a.pop(0))

    result = []
    i, j = len(left) - 1, len(right) - 1
    while i >= 0 and j >= 0:
        if left[i] < right[j]:
            result.append('R')
            j -= 1
        else:
            result.append('L')
            i -= 1

    while i >= 0:
        result.append('L')
        i -= 1

    while j >= 0:
        result.append('R')
        j -= 1

    return ''.join(reversed(result))

